#!/usr/bin/env python3
"""Summarize local runs without conflating training and deterministic evaluation.

Example (from this repository):
  python scripts/summarize_runs.py --trusted-checkpoints

Checkpoint unpickling is opt-in and restricted to paths within --runs-root. Use
--trusted-checkpoints only for checkpoints generated by your own local runs.
Missing or partially written inputs are skipped; rerun to refresh an active run.
"""

from __future__ import annotations

import argparse
import csv
import json
import math
import os
import re
import time
from datetime import datetime, timezone
from pathlib import Path

REPO = Path(__file__).resolve().parents[1]
TAGS = (
    "train/episode_norm_return", "train/episode_len", "wm/online_nse_8step",
    "wm/online_nse_1step", "policy/imag_survival_H", "policy/imag_reward_mean",
    "policy/critic_loss", "time/hours", "time/gpu_hours", "time/updates",
)


def finite(value):
    try:
        value = float(value)
        return value if math.isfinite(value) else None
    except (TypeError, ValueError):
        return None


def read_json(path, warnings):
    try:
        return json.loads(path.read_text())
    except (OSError, ValueError) as exc:
        warnings.append(f"Skipped {path}: {type(exc).__name__}: {exc}")
        return None


def scalar_series(run_dir, warnings):
    from tensorboard.backend.event_processing.event_accumulator import EventAccumulator

    tb = run_dir / "tb"
    if not tb.exists():
        return {}
    try:
        accumulator = EventAccumulator(str(tb), size_guidance={"scalars": 0}, purge_orphaned_data=False)
        accumulator.Reload()
        available = accumulator.Tags().get("scalars", [])
        result = {}
        for tag in TAGS:
            if tag not in available:
                continue
            by_step = {}
            for event in sorted(accumulator.Scalars(tag), key=lambda event: event.wall_time):
                value = finite(event.value)
                if value is not None:
                    by_step[event.step] = {"step": event.step, "value": value, "wall_time": event.wall_time}
            result[tag] = [by_step[step] for step in sorted(by_step)]
        return result
    except Exception as exc:
        warnings.append(f"Skipped TensorBoard input {tb}: {type(exc).__name__}: {exc}")
        return {}


def checkpoint_metadata(run_dir, runs_root, trusted, warnings):
    if not trusted:
        return None
    latest = run_dir / "ckpt_latest.pt"
    candidates = [latest] if latest.exists() else sorted(run_dir.glob("ckpt_[0-9]*.pt"), reverse=True)[:1]
    if not candidates:
        return None
    path = candidates[0]
    try:
        if not path.resolve().is_relative_to(runs_root.resolve()):
            raise ValueError("checkpoint resolves outside the trusted runs root")
        before = path.stat()
        if time.time() - before.st_mtime < 2:
            warnings.append(f"Skipped recently modified checkpoint {path}; rerun after its write completes")
            return None
        import torch

        checkpoint = torch.load(path, map_location="cpu", weights_only=False)
        after = path.stat()
        if (before.st_size, before.st_mtime_ns) != (after.st_size, after.st_mtime_ns):
            warnings.append(f"Skipped checkpoint modified during reading: {path}")
            return None
        metadata = {
            "path": str(path.resolve()), "iteration": int(checkpoint["iteration"]),
            "num_updates": int(checkpoint.get("num_updates", 0)),
            "compute": checkpoint.get("compute"),
        }
        del checkpoint
        return metadata
    except Exception as exc:
        warnings.append(f"Skipped checkpoint {path}: {type(exc).__name__}: {exc}")
        return None


def last(series, tag):
    values = series.get(tag, [])
    return values[-1] if values else None


def latest_value(series, tag):
    item = last(series, tag)
    return item["value"] if item else None


def summarize_run(run_dir, runs_root, trusted, warnings):
    config = read_json(run_dir / "config.json", warnings)
    if not isinstance(config, dict):
        return None
    series = scalar_series(run_dir, warnings)
    checkpoint = checkpoint_metadata(run_dir, runs_root, trusted, warnings)
    ck_compute = (checkpoint or {}).get("compute") or {}
    ck_step = (checkpoint or {}).get("iteration", -1)
    tb_clock = last(series, "time/hours")
    tb_gpu = last(series, "time/gpu_hours")
    seconds = finite(ck_compute.get("training_seconds"))
    gpu_hours = finite(ck_compute.get("gpu_hours"))
    clock_source = "checkpoint_compute" if seconds is not None else None
    clock_step = ck_step if seconds is not None else None
    if tb_clock and (seconds is None or tb_clock["step"] > ck_step):
        seconds = tb_clock["value"] * 3600
        clock_step = tb_clock["step"]
        clock_source = "tensorboard_time/hours"
    if tb_gpu and (gpu_hours is None or tb_gpu["step"] > ck_step):
        gpu_hours = tb_gpu["value"]
    row = {
        "run": run_dir.name,
        "seed": config.get("seed"),
        "checkpoint_iteration": (checkpoint or {}).get("iteration"),
        "latest_logged_iteration": max((p["step"] for v in series.values() for p in v), default=None),
        "training_seconds_observed": seconds,
        "gpu_hours_observed": gpu_hours,
        "clock_source": clock_source,
        "clock_iteration": clock_step,
        "compute_history_complete": ck_compute.get("history_complete"),
        "world_size_at_checkpoint": ck_compute.get("world_size_at_save"),
        "last_train_executed_step_norm_return": latest_value(series, "train/episode_norm_return"),
        "last_train_episode_length": latest_value(series, "train/episode_len"),
        "last_online_8step_state_error": latest_value(series, "wm/online_nse_8step"),
        "last_imagined_survival_H": latest_value(series, "policy/imag_survival_H"),
        "num_envs_per_gpu": config.get("env", {}).get("num_envs"),
        "anchor_obs": config.get("env", {}).get("anchor_obs"),
        "imagination_horizon": config.get("policy_trainer", {}).get("horizon"),
        "actor_batch_per_gpu": config.get("policy_trainer", {}).get("batch_size"),
        "config_path": str((run_dir / "config.json").resolve()),
    }
    return {"summary": row, "checkpoint": checkpoint, "scalars": series}


def summarize_benchmark(path, run_names, warnings):
    payload = read_json(path, warnings)
    if not isinstance(payload, dict) or not isinstance(payload.get("summary"), dict):
        return None
    source = payload["summary"]
    if "clips" not in source or "failed" not in source:
        return None
    run = path.parent.name if path.parent.name in run_names else None
    if run is None:
        run = next((name for name in sorted(run_names, key=len, reverse=True) if name in path.name), None)
    match = re.search(r"ckpt_(\d+)", path.stem)
    # A benchmark of ckpt_latest cannot safely inherit the current checkpoint's
    # iteration: that file may have been overwritten after evaluation.
    return {
        "run": run,
        "benchmark_path": str(path.resolve()),
        "checkpoint_iteration_from_filename": int(match.group(1)) if match else None,
        "clips": source.get("clips"), "failed": source.get("failed"),
        "mean_full_clip_norm_return": finite(source.get("mean_full_clip_norm_return")),
        "full_clip_step_weighted_norm_return": finite(source.get("full_clip_step_weighted_norm_return")),
        "mean_executed_steps_norm_return": finite(source.get("mean_executed_steps_norm_return", source.get("mean_norm_return"))),
        "executed_steps_weighted_norm_return": finite(source.get("executed_steps_weighted_norm_return", source.get("step_weighted_norm_return"))),
        "completion_fraction": finite(source.get("completion_fraction")),
        "scored_steps": source.get("scored_steps"), "planned_steps": source.get("planned_steps"),
        "protocol_note": source.get("protocol_note"),
    }


def write_json(path, value):
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(value, indent=2, allow_nan=False) + "\n")
    temporary.replace(path)


def write_csv(path, rows, fields):
    temporary = path.with_suffix(path.suffix + ".tmp")
    with temporary.open("w", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=fields, extrasaction="ignore")
        writer.writeheader()
        writer.writerows(rows)
    temporary.replace(path)


def plots(runs, benchmarks, out):
    # Keep matplotlib's cache local, and avoid requiring a graphical display.
    os.environ.setdefault("MPLCONFIGDIR", str(out / ".matplotlib"))
    import matplotlib

    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    specs = [
        ("train/episode_norm_return", "Training episode score", "Executed-step normalized reward"),
        ("wm/online_nse_8step", "World-model online error", "8-step normalized state error"),
        ("policy/imag_survival_H", "Imagination survival", "Mean survival at horizon H"),
        ("time/hours", "Observed training time", "Training loop hours"),
    ]
    fig, axes = plt.subplots(2, 2, figsize=(12, 8), constrained_layout=True)
    for axis, (tag, title, ylabel) in zip(axes.flat, specs):
        any_data = False
        for run in runs:
            points = run["scalars"].get(tag, [])
            if points:
                axis.plot(
                    [p["step"] for p in points], [p["value"] for p in points],
                    marker="o", markersize=3, markevery=max(1, len(points) // 20),
                    label=run["summary"]["run"],
                )
                any_data = True
        axis.set(title=title, xlabel="Global simulator iteration", ylabel=ylabel)
        axis.grid(alpha=0.2)
        if any_data:
            axis.legend(fontsize=8)
        else:
            axis.text(0.5, 0.5, "No scalar data recorded yet", transform=axis.transAxes, ha="center")
        if tag == "policy/imag_survival_H":
            axis.set_ylim(0, 1.02)
    fig.suptitle("Local training diagnostics", fontsize=13)
    fig.savefig(out / "training_curves.png", dpi=160)
    plt.close(fig)

    fig, axes = plt.subplots(1, 2, figsize=(12, max(4, 0.45 * len(benchmarks) + 1.5)), constrained_layout=True)
    if benchmarks:
        full_labeled = executed_labeled = False
        for i, bench in enumerate(benchmarks):
            full = bench["mean_full_clip_norm_return"]
            executed = bench["mean_executed_steps_norm_return"]
            if full is not None:
                axes[0].scatter(full, i - 0.1, marker="o", color="tab:blue", label="Full clip (primary)" if not full_labeled else None)
                full_labeled = True
            if executed is not None:
                axes[0].scatter(executed, i + 0.1, marker="x", color="tab:orange", label="Executed steps" if not executed_labeled else None)
                executed_labeled = True
            axes[1].barh(i, bench["failed"], color="tab:red", alpha=0.7)
            axes[1].text(bench["failed"], i, f" {bench['failed']}/{bench['clips']}", va="center", fontsize=8)
        labels = [f"{b['run'] or 'Unassigned run'}\n{Path(b['benchmark_path']).stem}" for b in benchmarks]
        for axis in axes:
            axis.set_yticks(range(len(labels)), labels)
            axis.set_ylim(-0.5, len(labels) - 0.5)
            axis.invert_yaxis()
            axis.grid(axis="x", alpha=0.2)
        handles, labels_legend = axes[0].get_legend_handles_labels()
        if handles:
            axes[0].legend(handles, labels_legend, fontsize=8)
        axes[0].set(xlabel="Mean normalized evaluation reward", title="Deterministic evaluation scores")
        axes[1].set(xlabel="Failed clips", title="Evaluation failures (count / evaluated clips)")
        axes[1].set_xlim(0, max(1, max(b["failed"] for b in benchmarks) * 1.18))
    else:
        for axis in axes:
            axis.axis("off")
            axis.text(0.5, 0.5, "No benchmark JSON available yet", ha="center", va="center")
    fig.suptitle("Deterministic benchmark evaluation", fontsize=13)
    fig.savefig(out / "evaluation_scores.png", dpi=160)
    plt.close(fig)


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--runs-root", type=Path, default=REPO / "runs")
    parser.add_argument("--out-dir", type=Path, default=REPO / "results")
    parser.add_argument("--run", action="append", help="Run directory name to include; repeat to select several")
    parser.add_argument("--benchmark", type=Path, action="append", default=[], help="Additional benchmark JSON; missing files are skipped")
    parser.add_argument("--trusted-checkpoints", action="store_true", help="Read ONLY your own generated local checkpoints using torch.load(weights_only=False)")
    args = parser.parse_args()
    args.out_dir.mkdir(parents=True, exist_ok=True)
    warnings = []
    run_dirs = sorted(p.parent for p in args.runs_root.glob("*/config.json"))
    if args.run:
        run_dirs = [p for p in run_dirs if p.name in args.run]
    runs = [r for p in run_dirs if (r := summarize_run(p, args.runs_root, args.trusted_checkpoints, warnings)) is not None]
    run_names = {r["summary"]["run"] for r in runs}
    benchmark_paths = set(args.benchmark)
    for run_dir in run_dirs:
        benchmark_paths.update(run_dir.glob("benchmark*.json"))
    # Explicit external paths are read as JSON only; no external pickle loading.
    benchmarks = [b for p in sorted(benchmark_paths) if (b := summarize_benchmark(p, run_names, warnings)) is not None]
    summary = {
        "schema_version": 1,
        "generated_at_utc": datetime.now(timezone.utc).isoformat(),
        "checkpoint_loading": "trusted_local_only" if args.trusted_checkpoints else "disabled",
        "notes": [
            "Snapshots do not determine whether a process is still running or completed.",
            "Training episode score uses executed steps; deterministic full-clip evaluation is separate.",
            "Timing is observed checkpoint/TensorBoard data; unlogged work is not extrapolated.",
            "No paper-level success, hardware equivalence, or generalization claim is inferred.",
            "Legacy time/hours may be per-process rather than cumulative; absent history metadata stays unknown.",
        ],
        "runs": [r["summary"] for r in runs], "benchmarks": benchmarks, "warnings": warnings,
    }
    write_json(args.out_dir / "run_summary.json", summary)
    write_json(args.out_dir / "scalar_history.json", {r["summary"]["run"]: r["scalars"] for r in runs})
    write_csv(args.out_dir / "run_summary.csv", summary["runs"], list(summary["runs"][0]) if runs else ["run"])
    write_csv(args.out_dir / "benchmark_summary.csv", benchmarks, list(benchmarks[0]) if benchmarks else ["run", "benchmark_path", "clips", "failed", "mean_full_clip_norm_return", "mean_executed_steps_norm_return"])
    plots(runs, benchmarks, args.out_dir)
    print(json.dumps({"runs": len(runs), "benchmarks": len(benchmarks), "warnings": len(warnings), "outputs": str(args.out_dir.resolve())}))
    for warning in warnings:
        print(f"WARNING: {warning}")


if __name__ == "__main__":
    main()
